<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Services\SystemSettings; use Illuminate\Http\Request;
class SystemSettingsController extends Controller { public function show(){return ['data'=>SystemSettings::all()];} public function update(Request $request){$data=$request->validate(['auto_matching'=>'required|boolean','match_on_category'=>'required|boolean','match_on_quantity'=>'required|boolean','max_matches_per_donation'=>'required|integer|between:1,50','match_cooldown_hours'=>'required|integer|between:0,168','email_handoff_alerts'=>'required|boolean','email_match_alerts'=>'required|boolean','email_approval_alerts'=>'required|boolean','handoff_reminder_hours'=>'required|integer|between:1,72','admin_verification'=>'required|boolean','require_justification'=>'required|boolean','auto_approve_returning'=>'required|boolean','max_pending_per_user'=>'required|integer|between:1,20','allow_self_registration'=>'required|boolean','maintenance_mode'=>'required|boolean','session_timeout_minutes'=>'required|integer|between:5,1440','max_photo_size_mb'=>'required|integer|between:1,10','items_per_page'=>'required|integer|between:5,100']);return ['data'=>SystemSettings::save($data,$request->user())];} }
